import React, { useState } from 'react';
import { Navbar } from './components/Navbar';
import { Footer } from './components/Footer';
import { CVBuilder } from './components/CVBuilder';
import { TemplatesGallery } from './components/TemplatesGallery';
import { ATSChecker } from './components/ATSChecker';
import { Dashboard } from './components/Dashboard';
import { initialCVData } from './data/mockData';
import { CVData, Language, TemplateStyle } from './types/cv';

export function App() {
  const [activeTab, setActiveTab] = useState<string>('builder');
  const [language, setLanguage] = useState<Language>('en');
  const [cvData, setCvData] = useState<CVData>(initialCVData);

  const handleSelectTemplate = (templateId: TemplateStyle) => {
    setCvData({ ...cvData, templateId });
    setActiveTab('builder');
  };

  return (
    <div className="min-h-screen flex flex-col bg-background text-foreground selection:bg-primary/20">
      <Navbar 
        activeTab={activeTab} 
        setActiveTab={setActiveTab} 
        language={language} 
        setLanguage={setLanguage} 
      />

      <main className="flex-1">
        {activeTab === 'builder' && (
          <CVBuilder cvData={cvData} setCvData={setCvData} language={language} />
        )}
        {activeTab === 'templates' && (
          <TemplatesGallery language={language} onSelectTemplate={handleSelectTemplate} />
        )}
        {activeTab === 'ats' && (
          <ATSChecker language={language} cvData={cvData} />
        )}
        {activeTab === 'dashboard' && (
          <Dashboard language={language} cvData={cvData} setActiveTab={setActiveTab} />
        )}
      </main>

      <Footer language={language} />
    </div>
  );
}

export default App;
