export type Language = 'en' | 'ar';

export type TemplateStyle = 
  | 'modern' 
  | 'executive' 
  | 'tech' 
  | 'creative' 
  | 'minimalist'
  | 'startup'
  | 'academic'
  | 'timeline';

export interface PersonalInfo {
  fullName: string;
  jobTitle: string;
  email: string;
  phone: string;
  location: string;
  website: string;
  summary: string;
  avatarUrl?: string;
}

export interface Experience {
  id: string;
  company: string;
  position: string;
  location: string;
  startDate: string;
  endDate: string;
  current: boolean;
  description: string;
  highlights: string[];
}

export interface Education {
  id: string;
  institution: string;
  degree: string;
  field: string;
  startDate: string;
  endDate: string;
