            <div className="space-y-3">
              <h2 className="text-xs font-bold uppercase tracking-widest text-slate-900 bg-slate-100 p-1.5 rounded">
                {isAr ? 'الخبرات المهنية' : 'Experience'}
              </h2>
              {experiences.map((exp) => (
                <div key={exp.id} className="space-y-1">
                  <div className="flex justify-between font-bold text-slate-900">
                    <span>{exp.position} | {exp.company}</span>
                    <span className="text-slate-500">{exp.startDate} - {exp.current ? 'Present' : exp.endDate}</span>
                  </div>
                  <p className="text-slate-700">{exp.description}</p>
                </div>
              ))}
            </div>
          )}
        </div>
      )}

      {/* 6. Startup / Bold Founder Template */}
      {templateId === 'startup' && (
        <div className="space-y-6 bg-slate-950 text-slate-100 p-8 rounded-2xl">
          <div className="border-b border-slate-800 pb-6 flex items-center justify-between">
            <div>
              <span className="text-xs font-mono text-amber-400">// STARTUP_FOUNDER</span>
              <h1 className="text-3xl font-extrabold text-white mt-1">{personalInfo?.fullName}</h1>
              <p className="text-sm text-slate-400">{personalInfo?.jobTitle}</p>
            </div>
            {personalInfo?.avatarUrl && (
              <img src={personalInfo.avatarUrl} alt="" className="w-16 h-16 rounded-full border-2 border-amber-400 object-cover" />
            )}
          </div>
          {personalInfo?.summary && (
            <p className="text-slate-300 leading-relaxed border-l-2 border-amber-400 pl-4">{personalInfo.summary}</p>
          )}
          {experiences.length > 0 && (
            <div className="space-y-4">
              <h2 className="text-xs font-mono uppercase tracking-widest text-amber-400">Venture History</h2>
              {experiences.map(exp => (
                <div key={exp.id} className="space-y-1 bg-slate-900 p-4 rounded-xl border border-slate-800">
                  <div className="flex justify-between font-bold text-white">
                    <span>{exp.position} @ {exp.company}</span>
                    <span className="text-amber-400">{exp.startDate}</span>
                  </div>
                  <p className="text-slate-400">{exp.description}</p>
                </div>
              ))}
            </div>
          )}
        </div>
      )}

      {/* 7. Academic / Researcher Template */}
      {templateId === 'academic' && (
        <div className="space-y-6 font-serif bg-amber-50/30 p-6 rounded-xl border border-amber-900/10">
          <div className="text-center border-b border-amber-900/20 pb-6 space-y-2">
            <h1 className="text-3xl font-bold tracking-wide text-amber-950">{personalInfo?.fullName}</h1>
            <p className="text-xs font-sans tracking-widest text-amber-800 uppercase">{personalInfo?.jobTitle}</p>
            <div className="text-xs text-slate-600 font-sans">
              {personalInfo?.email} • {personalInfo?.location}
            </div>
          </div>
          {personalInfo?.summary && (
            <div className="space-y-1">
              <h3 className="text-xs font-bold uppercase tracking-wider text-amber-900 font-sans">Research Focus</h3>
              <p className="text-slate-800 leading-relaxed italic">{personalInfo.summary}</p>
            </div>
          )}
          {education.length > 0 && (
            <div className="space-y-2">
              <h3 className="text-xs font-bold uppercase tracking-wider text-amber-900 font-sans">Academic Background</h3>
              {education.map(edu => (
                <div key={edu.id} className="space-y-0.5">
                  <div className="font-bold text-slate-900">{edu.degree} in {edu.field}</div>
                  <div className="text-slate-600">{edu.institution} ({edu.startDate} - {edu.endDate})</div>
                </div>
              ))}
            </div>
          )}
        </div>
      )}

      {/* 8. Timeline Elegant Template */}
      {templateId === 'timeline' && (
        <div className="space-y-6">
          <div className="border-b pb-6 space-y-1 text-center">
            <h1 className="text-3xl font-bold tracking-tight" style={{ color: accentColor }}>{personalInfo?.fullName}</h1>
            <p className="font-semibold text-slate-600">{personalInfo?.jobTitle}</p>
          </div>
          {personalInfo?.summary && (
            <p className="text-slate-700 text-center max-w-lg mx-auto">{personalInfo.summary}</p>
          )}
          {experiences.length > 0 && (
            <div className="space-y-4 border-l-2 ml-4 pl-4" style={{ borderColor: accentColor }}>
              {experiences.map(exp => (
                <div key={exp.id} className="space-y-1 relative">
                  <div className="absolute -left-[21px] top-1 w-3 h-3 rounded-full bg-white border-2" style={{ borderColor: accentColor }} />
                  <span className="text-[10px] font-bold px-2 py-0.5 rounded bg-slate-100 text-slate-700">{exp.startDate}</span>
                  <h3 className="font-bold text-slate-900">{exp.position} - {exp.company}</h3>
                  <p className="text-slate-600">{exp.description}</p>
                </div>
              ))}
            </div>
          )}
        </div>
      )}
    </div>
  );
};
</boltAction>

<boltAction type="start">
npm run dev
</boltAction>
